/** Item generators, answer checks and hints for every MVP skill.
 *  Every item is generated by rule; the same answer is never used twice in a session. */
import { int, pick, Rng, shuffle } from "./rng";
import { ColumnBug, diagnoseWhole } from "./column";
import type { Lang } from "./skills";
import { C1Item, C1Mistake, C1_MISTAKE_TEXT, c1AnswerKey, c1Choices, checkClass1, feedbackClass1, genClass1, hintClass1, promptClass1 } from "./class1";

export type Step = 1 | 2 | 3;          // difficulty inside a skill: 1 easiest

export type Item =
  | { kind: "pv_build"; skill: string; n: number }
  | { kind: "pv_read"; skill: string; n: number }
  | { kind: "pv_compare"; skill: string; a: number; b: number }
  | { kind: "money_add"; skill: string; toys: [string, string]; prices: [number, number] }
  | { kind: "money_change"; skill: string; toy: string; price: number; paid: number }
  | { kind: "share"; skill: string; total: number; plates: number; food: string }
  | { kind: "fraction"; skill: string; parts: 2 | 4; food: string; options: FractionOption[] }
  | { kind: "h_build"; skill: string; n: number }
  | { kind: "column"; skill: string; a: number; b: number; op: "+" | "-" }
  | C1Item;

export interface FractionOption { id: string; cuts: number[] }   // cut positions as % of width; equal when evenly spaced

export type Mistake = ColumnBug | "wrong_op" | "reversed_digits" | "ones_over_9" | "compared_ones" | "unequal_share"
  | "left_too_many" | "unequal_parts" | "miscount" | C1Mistake;

export const MISTAKE_TEXT: Record<Mistake, Record<Lang, string>> = {
  ...C1_MISTAKE_TEXT,
  smaller_from_larger: { en: "Takes the smaller digit from the larger in a column", hi: "कॉलम में बड़े अंक से छोटा अंक घटा देते हैं" },
  no_decrement: { en: "Forgets that a ten was given to the column on the right", hi: "भूल जाते हैं कि एक दहाई दाईं ओर दी गई थी" },
  ambiguous_trade: { en: "Unclear how the ones were worked out", hi: "इकाई कैसे निकाली, यह साफ़ नहीं" },
  no_carry: { en: "Forgets to carry the ten", hi: "हासिल जोड़ना भूल जाते हैं" },
  unneeded_trade: { en: "Trades a ten when it isn't needed", hi: "ज़रूरत न होने पर भी दहाई बदलते हैं" },
  wrong_digit: { en: "Calculation slip", hi: "गिनती में चूक" },
  wrong_op: { en: "Added instead of subtracting (or the other way)", hi: "घटाने की जगह जोड़ दिया (या उल्टा)" },
  reversed_digits: { en: "Swaps tens and ones (writes 34 for 43)", hi: "दहाई और इकाई उलट देते हैं (43 की जगह 34)" },
  ones_over_9: { en: "Keeps 10 or more loose ones instead of making a ten", hi: "10 या ज़्यादा इकाई को दहाई नहीं बनाते" },
  compared_ones: { en: "Compares the ones digits instead of the tens", hi: "दहाई की जगह इकाई की तुलना करते हैं" },
  unequal_share: { en: "Shares unequally", hi: "बराबर नहीं बाँटते" },
  left_too_many: { en: "Leaves over more than could still be shared", hi: "जितने और बाँटे जा सकते थे, उससे ज़्यादा छोड़ देते हैं" },
  unequal_parts: { en: "Thinks any 2 pieces are halves, even if unequal", hi: "किसी भी 2 टुकड़ों को आधा मान लेते हैं, चाहे बराबर न हों" },
};

const TOYS = ["kite", "top", "drum", "doll", "ball", "whistle", "car", "flute"];
const FOODS = ["laddoo", "jalebi", "barfi", "peda"];
const SLABS = ["chikki", "paratha", "sandwich"];   // drawn as rectangles so straight cuts can be fair

/** Answers already used this session, so no answer repeats (a child must not pass by repeating 25). */
export class AnswerSet {
  used = new Set<string>();
  has(key: string) { return this.used.has(key); }
  add(key: string) { this.used.add(key); }
}

const answerKey = (it: Item): string => {
  switch (it.kind) {
    case "pv_build": case "pv_read": case "h_build": return `n${it.n}`;
    case "pv_compare": return `c${Math.max(it.a, it.b)}`;
    case "money_add": return `n${it.prices[0] + it.prices[1]}`;
    case "money_change": return `n${it.paid - it.price}`;
    case "share": return `s${it.total}/${it.plates}`;
    case "fraction": return `f${it.parts}${it.food}`;
    case "column": return `n${it.op === "+" ? it.a + it.b : it.a - it.b}`;
    default: return c1AnswerKey(it);
  }
};

function gen(skill: string, step: Step, rng: Rng): Item {
  switch (skill) {
    case "pv_build": case "pv_read": {
      const kind = skill as "pv_build" | "pv_read";
      if (step === 1) return { kind, skill, n: int(rng, 2, 5) * 10 + int(rng, 1, 9) };
      if (step === 2) return { kind, skill, n: int(rng, 1, 9) * 10 + int(rng, 1, 9) };
      return { kind, skill, n: pick(rng, [int(rng, 1, 9) * 10, 10 + int(rng, 1, 9), int(rng, 6, 9) * 10 + int(rng, 0, 9)]) };
    }
    case "pv_compare": {
      // step 3 uses digit swaps (52 vs 25), the classic trap
      const t = int(rng, 2, 9), o = int(rng, 1, 9);
      if (step === 3 && t !== o) return { kind: "pv_compare", skill, a: t * 10 + o, b: o * 10 + t };
      const a = t * 10 + o;
      let b = step === 1 ? int(rng, 1, 9) * 10 + int(rng, 0, 9) : (t + (rng() < 0.5 ? 1 : -1)) * 10 + int(rng, 0, 9);
      if (b === a || b < 10 || b > 99) b = a > 50 ? a - 11 : a + 11;
      return { kind: "pv_compare", skill, a, b };
    }
    case "money_add": {
      // no carrying: ones digits sum to 9 or less
      const max = step === 1 ? 20 : 50;
      const t1 = int(rng, 1, Math.floor(max / 10) - 1 || 1), t2 = int(rng, 1, Math.max(1, Math.floor(max / 10) - t1));
      const o1 = int(rng, 1, 8), o2 = int(rng, 0, 9 - o1);
      const toys = shuffle(rng, TOYS).slice(0, 2) as [string, string];
      return { kind: "money_add", skill, toys, prices: [t1 * 10 + o1, t2 * 10 + o2] };
    }
    case "money_add_carry": {
      const o1 = int(rng, 3, 9), o2 = int(rng, 10 - o1, 9);
      const t1 = int(rng, 1, step === 1 ? 2 : 4), t2 = int(rng, 1, step === 1 ? 2 : Math.max(1, 8 - t1));
      const toys = shuffle(rng, TOYS).slice(0, 2) as [string, string];
      return { kind: "money_add", skill: "money_add_carry", toys, prices: [t1 * 10 + o1, t2 * 10 + o2] };
    }
    case "money_change": {
      const paid = step === 1 ? 20 : step === 2 ? 50 : 100;
      // price ones digit > 0 so change needs regrouping, except step 1 which may not
      const price = step === 1 ? int(rng, 11, 18) : (int(rng, 1, paid / 10 - 1) * 10 + int(rng, 1, 9));
      return { kind: "money_change", skill, toy: pick(rng, TOYS), price, paid };
    }
    case "share_equal": {
      const plates = step === 1 ? 2 : int(rng, 3, step === 2 ? 4 : 5);
      const each = int(rng, 2, step === 3 ? 6 : 4);
      return { kind: "share", skill, total: plates * each, plates, food: pick(rng, FOODS) };
    }
    case "share_left": {
      const plates = int(rng, step === 1 ? 2 : 3, step === 3 ? 5 : 4);
      const each = int(rng, 2, 4), left = int(rng, 1, plates - 1);
      return { kind: "share", skill, total: plates * each + left, plates, food: pick(rng, FOODS) };
    }
    case "share_fraction": {
      const parts: 2 | 4 = step === 1 ? 2 : pick(rng, [2, 4] as const);
      const even = parts === 2 ? [50] : [25, 50, 75];
      const wrong1 = parts === 2 ? [32] : [20, 45, 80];
      const wrong2 = parts === 2 ? [66] : [33, 66];   // 3 pieces when 4 asked; for halves, uneven again
      const options = shuffle(rng, [{ id: "even", cuts: even }, { id: "w1", cuts: wrong1 }, { id: "w2", cuts: wrong2 }]);
      return { kind: "fraction", skill, parts, food: pick(rng, SLABS), options };
    }
    case "h_build": {
      const h = int(rng, 1, 9);
      if (step === 1) return { kind: "h_build", skill, n: h * 100 + int(rng, 1, 5) * 10 + int(rng, 1, 5) };
      if (step === 2) return { kind: "h_build", skill, n: h * 100 + int(rng, 1, 9) * 10 + int(rng, 1, 9) };
      return { kind: "h_build", skill, n: h * 100 + pick(rng, [0, int(rng, 1, 9) * 10]) + pick(rng, [0, int(rng, 1, 9)]) };
    }
    case "h_add": {
      // step 1: one trade in the ones; step 2: trade in ones and tens; step 3: also into hundreds... kept under 1000
      const a1 = int(rng, 1, 4), b1 = int(rng, 1, 4);
      const ao = int(rng, 3, 9), bo = int(rng, 10 - ao, 9);
      const at = step === 1 ? int(rng, 1, 4) : int(rng, 4, 8), bt = step === 1 ? int(rng, 0, 8 - at) : int(rng, 9 - at, 9);
      const a = a1 * 100 + at * 10 + ao, b = b1 * 100 + bt * 10 + bo;
      return { kind: "column", skill, a, b, op: "+" };
    }
    case "h_sub": {
      const ah = int(rng, 4, 9), bh = int(rng, 1, ah - 1);
      const ao = int(rng, 0, 6), bo = int(rng, ao + 1, 9);
      const at = step === 1 ? int(rng, 3, 9) : int(rng, 0, 5);
      const bt = step === 1 ? int(rng, 0, at - 1) : int(rng, Math.min(9, at), 9);
      return { kind: "column", skill, a: ah * 100 + at * 10 + ao, b: bh * 100 + bt * 10 + bo, op: "-" };
    }
  }
  const c1 = genClass1(skill, step, rng);
  if (c1) return c1;
  throw new Error(`No generator for ${skill}`);
}

/** A fresh item for this skill and step whose answer has not been used this session. */
export function nextItem(skill: string, step: Step, rng: Rng, used: AnswerSet): Item {
  let it = gen(skill, step, rng);
  for (let i = 0; i < 40 && used.has(answerKey(it)); i++) it = gen(skill, step, rng);
  used.add(answerKey(it));
  return it;
}

/** How many choices the child had (guessing is easier with fewer). 0 = open answer. */
export const choices = (it: Item) => (it.kind === "pv_compare" ? 2 : it.kind === "fraction" ? 3 : isC1(it) ? c1Choices(it) : 0);
const C1_KINDS = ["count", "bond", "arith1", "pick"];
export const isC1 = (it: Item): it is C1Item => C1_KINDS.includes(it.kind);

// ---------- checking ----------

export type Answer =
  | { tens: number; ones: number }
  | { hundreds: number; tens: number; ones: number }
  | { value: number }
  | { pick: "a" | "b" | string }
  | { plates: number[]; left: number }
  | { word: string };

export interface Check { ok: boolean; mistake?: Mistake }

export function check(it: Item, ans: Answer): Check {
  if (isC1(it)) return checkClass1(it, ans as { value?: number; pick?: string; word?: string });
  switch (it.kind) {
    case "pv_build": {
      const { tens, ones } = ans as { tens: number; ones: number };
      if (tens * 10 + ones === it.n && ones < 10) return { ok: true };
      if (tens === it.n % 10 && ones === Math.floor(it.n / 10)) return { ok: false, mistake: "reversed_digits" };
      if (tens * 10 + ones === it.n) return { ok: false, mistake: "ones_over_9" };
      return { ok: false, mistake: "miscount" };
    }
    case "pv_read": case "h_build": {
      const v = "value" in ans ? ans.value : "hundreds" in ans ? ans.hundreds * 100 + ans.tens * 10 + ans.ones : -1;
      if ("hundreds" in ans && ans.ones > 9) return { ok: false, mistake: "ones_over_9" };
      if ("hundreds" in ans && ans.tens > 9) return { ok: false, mistake: "ones_over_9" };
      if (v === it.n) return { ok: true };
      const rev = Number(String(it.n).split("").reverse().join(""));
      return { ok: false, mistake: v === rev ? "reversed_digits" : "miscount" };
    }
    case "pv_compare": {
      const bigger = it.a > it.b ? "a" : "b";
      const p = (ans as { pick: string }).pick;
      if (p === bigger) return { ok: true };
      const onesBigger = it.a % 10 > it.b % 10 ? "a" : "b";
      return { ok: false, mistake: p === onesBigger ? "compared_ones" : "miscount" };
    }
    case "money_add": {
      const v = (ans as { value: number }).value;
      const m = diagnoseWhole(it.prices[0], it.prices[1], "+", v);
      return m ? { ok: false, mistake: m } : { ok: true };
    }
    case "money_change": {
      const v = (ans as { value: number }).value;
      const m = diagnoseWhole(it.paid, it.price, "-", v);
      return m ? { ok: false, mistake: m } : { ok: true };
    }
    case "share": {
      const { plates, left } = ans as { plates: number[]; left: number };
      const each = Math.floor(it.total / it.plates), rest = it.total % it.plates;
      const equal = plates.every(p => p === plates[0]);
      if (!equal) return { ok: false, mistake: "unequal_share" };
      if (plates[0] === each && left === rest) return { ok: true };
      if (left >= it.plates) return { ok: false, mistake: "left_too_many" };
      return { ok: false, mistake: "miscount" };
    }
    case "fraction": {
      const p = (ans as { pick: string }).pick;
      return p === "even" ? { ok: true } : { ok: false, mistake: "unequal_parts" };
    }
    case "column":
      return { ok: false };   // column items are checked step by step in column.ts
  }
}

// ---------- spoken prompts and hints ----------

const T = (lang: Lang, en: string, hi: string) => (lang === "hi" ? hi : en);
const toyName: Record<string, Record<Lang, string>> = {
  kite: { en: "kite", hi: "पतंग" }, top: { en: "spinning top", hi: "लट्टू" }, drum: { en: "drum", hi: "ढोल" },
  doll: { en: "doll", hi: "गुड़िया" }, ball: { en: "ball", hi: "गेंद" }, whistle: { en: "whistle", hi: "सीटी" },
  car: { en: "toy car", hi: "खिलौना गाड़ी" }, flute: { en: "flute", hi: "बाँसुरी" },
};
const foodName: Record<string, Record<Lang, string>> = {
  laddoo: { en: "laddoos", hi: "लड्डू" }, jalebi: { en: "jalebis", hi: "जलेबियाँ" }, barfi: { en: "barfis", hi: "बर्फ़ियाँ" },
  peda: { en: "pedas", hi: "पेड़े" }, chikki: { en: "chikki", hi: "चिक्की" }, paratha: { en: "paratha", hi: "पराठा" }, sandwich: { en: "sandwich", hi: "सैंडविच" },
};
export const toyLabel = (t: string, lang: Lang) => toyName[t]?.[lang] ?? t;
export const foodLabel = (f: string, lang: Lang) => foodName[f]?.[lang] ?? f;

export function prompt(it: Item, lang: Lang): string {
  if (isC1(it)) return promptClass1(it, lang);
  switch (it.kind) {
    case "pv_build": return T(lang, `Make a necklace with ${it.n} beads.`, `${it.n} मोतियों का हार बनाओ।`);
    case "pv_read": return T(lang, "How many beads are on this necklace?", "इस हार में कितने मोती हैं?");
    case "pv_compare": return T(lang, "Which necklace has more beads?", "किस हार में ज़्यादा मोती हैं?");
    case "money_add": return T(lang,
      `I want a ${toyLabel(it.toys[0], lang)} for ₹${it.prices[0]} and a ${toyLabel(it.toys[1], lang)} for ₹${it.prices[1]}. How much is that?`,
      `मुझे ${toyLabel(it.toys[0], lang)} (₹${it.prices[0]}) और ${toyLabel(it.toys[1], lang)} (₹${it.prices[1]}) चाहिए। कुल कितने रुपये हुए?`);
    case "money_change": return T(lang,
      `The ${toyLabel(it.toy, lang)} costs ₹${it.price}. I am giving you ₹${it.paid}. How much change do I get?`,
      `${toyLabel(it.toy, lang)} का दाम ₹${it.price} है। मैं ₹${it.paid} दे रहा हूँ। मुझे कितने रुपये वापस मिलेंगे?`);
    case "share": return it.skill === "share_left"
      ? T(lang, `Share ${it.total} ${foodLabel(it.food, lang)} equally among ${it.plates} plates. Put any left over in the box.`,
          `${it.total} ${foodLabel(it.food, lang)} ${it.plates} थालियों में बराबर बाँटो। जो बचें, डिब्बे में रखो।`)
      : T(lang, `Share ${it.total} ${foodLabel(it.food, lang)} equally among ${it.plates} plates.`,
          `${it.total} ${foodLabel(it.food, lang)} ${it.plates} थालियों में बराबर बाँटो।`);
    case "fraction": return it.parts === 2
      ? T(lang, `Which ${foodLabel(it.food, lang)} is cut into 2 equal halves?`, `किस तस्वीर में ${foodLabel(it.food, lang)} के 2 बराबर आधे हिस्से हैं?`)
      : T(lang, `Which ${foodLabel(it.food, lang)} is cut into 4 equal quarters?`, `किस तस्वीर में ${foodLabel(it.food, lang)} के 4 बराबर चौथाई हिस्से हैं?`);
    case "h_build": return T(lang, `Build ${it.n} with blocks.`, `ब्लॉकों से ${it.n} बनाओ।`);
    case "column": return it.op === "+"
      ? T(lang, `A delivery! Add ${it.b} bricks to ${it.a}. Start with the ones.`, `सामान आया! ${it.a} ईंटों में ${it.b} जोड़ो। इकाई से शुरू करो।`)
      : T(lang, `${it.b} bricks are used. Take ${it.b} from ${it.a}. Start with the ones.`, `${it.b} ईंटें लग गईं। ${it.a} में से ${it.b} घटाओ। इकाई से शुरू करो।`);
  }
}

/** Hint for level 1 (nudge), 2 (show the picture aid), 3 (worked step), 4 (answer for this step; only on request). */
export function hint(it: Item, level: number, lang: Lang): string {
  if (isC1(it)) return hintClass1(it, level, lang);
  const L = Math.max(1, Math.min(4, level));
  switch (it.kind) {
    case "pv_build": {
      const t = Math.floor(it.n / 10), o = it.n % 10;
      return [T(lang, "Each string has 10 beads. How many tens are in the number?", "हर लड़ी में 10 मोती हैं। संख्या में कितनी दहाई हैं?"),
        T(lang, `Look at the first digit of ${it.n}. That is how many strings of 10.`, `${it.n} का पहला अंक देखो। उतनी 10 वाली लड़ियाँ।`),
        T(lang, `${it.n} is ${t} tens and ${o} ones.`, `${it.n} में ${t} दहाई और ${o} इकाई हैं।`),
        T(lang, `Use ${t} strings and ${o} single beads.`, `${t} लड़ियाँ और ${o} अकेले मोती लो।`)][L - 1];
    }
    case "pv_read": case "h_build": {
      const h = Math.floor(it.n / 100), t = Math.floor(it.n / 10) % 10, o = it.n % 10;
      const parts = it.kind === "h_build" ? T(lang, `${h} hundreds, ${t} tens and ${o} ones`, `${h} सैकड़ा, ${t} दहाई और ${o} इकाई`)
        : T(lang, `${t} tens and ${o} ones`, `${t} दहाई और ${o} इकाई`);
      return [T(lang, "Count the big groups first, then the small ones.", "पहले बड़े समूह गिनो, फिर छोटे।"),
        T(lang, "Each string or rod is 10. Count them in tens: 10, 20, 30...", "हर लड़ी या छड़ 10 की है। दस-दस करके गिनो: 10, 20, 30..."),
        T(lang, `It has ${parts}.`, `इसमें ${parts} हैं।`),
        T(lang, `So the number is ${it.n}.`, `तो संख्या ${it.n} है।`)][L - 1];
    }
    case "pv_compare": {
      const big = Math.max(it.a, it.b);
      return [T(lang, "Look at the strings of 10 first.", "पहले 10 वाली लड़ियाँ देखो।"),
        T(lang, "The necklace with more strings has more beads, whatever the single beads.", "जिस हार में ज़्यादा लड़ियाँ हैं, उसमें ज़्यादा मोती हैं।"),
        T(lang, `${it.a} has ${Math.floor(it.a / 10)} tens. ${it.b} has ${Math.floor(it.b / 10)} tens.`, `${it.a} में ${Math.floor(it.a / 10)} दहाई। ${it.b} में ${Math.floor(it.b / 10)} दहाई।`),
        T(lang, `${big} is more.`, `${big} ज़्यादा है।`)][L - 1];
    }
    case "money_add": {
      const [p, q] = it.prices, ones = (p % 10) + (q % 10);
      return [T(lang, "Add the ₹1 coins first, then the ₹10 notes.", "पहले ₹1 के सिक्के जोड़ो, फिर ₹10 के नोट।"),
        T(lang, "Look at the coins and notes on the counter.", "काउंटर पर रखे सिक्के और नोट देखो।"),
        ones > 9 ? T(lang, `${p % 10} + ${q % 10} = ${ones} ones. That makes 1 more ten.`, `${p % 10} + ${q % 10} = ${ones} इकाई। इससे 1 दहाई और बनी।`)
          : T(lang, `Ones: ${p % 10} + ${q % 10} = ${ones}. Tens: ${Math.floor(p / 10)} + ${Math.floor(q / 10)}.`, `इकाई: ${p % 10} + ${q % 10} = ${ones}। दहाई: ${Math.floor(p / 10)} + ${Math.floor(q / 10)}।`),
        T(lang, `₹${p} + ₹${q} = ₹${p + q}.`, `₹${p} + ₹${q} = ₹${p + q}।`)][L - 1];
    }
    case "money_change": {
      const c = it.paid - it.price;
      return [T(lang, `Count up from ₹${it.price} to ₹${it.paid}.`, `₹${it.price} से ₹${it.paid} तक आगे गिनो।`),
        T(lang, "Use the number line: jump to the next ten first.", "संख्या रेखा देखो: पहले अगली दहाई तक कूदो।"),
        T(lang, `₹${it.price} to ₹${Math.ceil(it.price / 10) * 10} is ₹${Math.ceil(it.price / 10) * 10 - it.price}. Then on to ₹${it.paid}.`,
          `₹${it.price} से ₹${Math.ceil(it.price / 10) * 10} तक ₹${Math.ceil(it.price / 10) * 10 - it.price}। फिर ₹${it.paid} तक।`),
        T(lang, `The change is ₹${c}.`, `बाकी ₹${c} हैं।`)][L - 1];
    }
    case "share": {
      const each = Math.floor(it.total / it.plates), rest = it.total % it.plates;
      return [T(lang, "Give one to each plate, then go round again.", "हर थाली में एक-एक रखो, फिर दोबारा घुमाओ।"),
        T(lang, "Check: does every plate have the same number?", "देखो: क्या हर थाली में बराबर हैं?"),
        T(lang, `${it.plates} plates. ${it.plates} × ${each} = ${it.plates * each}.`, `${it.plates} थालियाँ। ${it.plates} × ${each} = ${it.plates * each}।`),
        rest ? T(lang, `Each plate gets ${each}, and ${rest} are left.`, `हर थाली में ${each}, और ${rest} बचे।`)
          : T(lang, `Each plate gets ${each}.`, `हर थाली में ${each}।`)][L - 1];
    }
    case "fraction":
      return [T(lang, "Halves and quarters must be the same size.", "आधे और चौथाई हिस्से एक जैसे बड़े होने चाहिए।"),
        T(lang, "Look at each piece. Are they all the same size?", "हर टुकड़ा देखो। क्या सब बराबर हैं?"),
        T(lang, `Find the one with ${it.parts} pieces that are all the same.`, `वह ढूँढो जिसमें ${it.parts} टुकड़े बिल्कुल बराबर हैं।`),
        T(lang, "It is the one with the cuts evenly spaced.", "वही जिसमें कटाई बराबर दूरी पर है।")][L - 1];
    case "column": {
      const ans = it.op === "+" ? it.a + it.b : it.a - it.b, ao = it.a % 10, bo = it.b % 10;
      const ones = it.op === "+"
        ? (ao + bo > 9 ? T(lang, `Ones: ${ao} + ${bo} = ${ao + bo}. Write ${(ao + bo) % 10} and carry 1 ten.`, `इकाई: ${ao} + ${bo} = ${ao + bo}। ${(ao + bo) % 10} लिखो और 1 दहाई आगे ले जाओ।`)
                       : T(lang, `Ones: ${ao} + ${bo} = ${ao + bo}.`, `इकाई: ${ao} + ${bo} = ${ao + bo}।`))
        : (ao < bo ? T(lang, `Ones: ${ao} is less than ${bo}, so open a ten: ${ao + 10} − ${bo} = ${ao + 10 - bo}.`, `इकाई: ${ao}, ${bo} से छोटा है, तो एक दहाई खोलो: ${ao + 10} − ${bo} = ${ao + 10 - bo}।`)
                   : T(lang, `Ones: ${ao} − ${bo} = ${ao - bo}.`, `इकाई: ${ao} − ${bo} = ${ao - bo}।`));
      return [T(lang, "Work one column at a time, starting with the ones.", "एक-एक कॉलम करो, इकाई से शुरू करो।"),
        T(lang, "Look at the blocks for the top number.", "ऊपर वाली संख्या के ब्लॉक देखो।"),
        ones,
        T(lang, `Then the tens and hundreds the same way. ${it.a} ${it.op === "+" ? "+" : "−"} ${it.b} = ${ans}.`, `फिर दहाई और सैकड़ा भी ऐसे ही। ${it.a} ${it.op === "+" ? "+" : "−"} ${it.b} = ${ans}।`)][L - 1];
    }
  }
}

/** Short, task-focused words after a known mistake. */
export function mistakeFeedback(m: Mistake | undefined, lang: Lang): string {
  switch (m) {
    case "reversed_digits": return T(lang, "The first digit tells the tens. Try again.", "पहला अंक दहाई बताता है। फिर से करो।");
    case "ones_over_9": return T(lang, "10 single ones make one ten. Can you swap them?", "10 इकाई से एक दहाई बनती है। बदल सकते हो?");
    case "compared_ones": return T(lang, "Tens matter most. Compare the tens first.", "दहाई सबसे ज़रूरी है। पहले दहाई मिलाओ।");
    case "smaller_from_larger": return T(lang, "Always take the bottom from the top. If the top is smaller, open a ten.", "हमेशा ऊपर वाले में से नीचे वाला घटाओ। ऊपर छोटा हो तो एक दहाई खोलो।");
    case "no_decrement": return T(lang, "One ten was opened, so there is one less ten now.", "एक दहाई खोली गई थी, तो अब एक दहाई कम है।");
    case "ambiguous_trade": return T(lang, "How did you get the ones? Show me with the blocks.", "इकाई कैसे निकाली? ब्लॉकों से दिखाओ।");
    case "no_carry": return T(lang, "Don't forget the ten you carried.", "हासिल वाली दहाई मत भूलो।");
    case "wrong_op": return T(lang, "Is this a taking-away or a putting-together?", "यह घटाना है या जोड़ना?");
    case "unequal_share": return T(lang, "The plates are not the same. Everyone should get the same.", "थालियाँ बराबर नहीं हैं। सबको बराबर मिलना चाहिए।");
    case "left_too_many": return T(lang, "There are enough left to give one more to each plate.", "इतने बचे हैं कि हर थाली में एक और दे सकते हो।");
    case "unequal_parts": return T(lang, "Those pieces are not the same size.", "वे टुकड़े बराबर नहीं हैं।");
    case "unneeded_trade": return T(lang, "This column doesn't need a trade. Look again.", "इस कॉलम में बदलने की ज़रूरत नहीं। फिर से देखो।");
    case "chose_opposite": case "off_by_one": case "overfilled": case "end_sound": case "letter_reversal": case "vowel_swap":
    case "letters_out_of_order": case "near_word": case "near_shape": case "wrong_pick": case "same_start":
      return feedbackClass1(m, lang);
    default: return T(lang, "Not yet. Look again.", "अभी नहीं। फिर से देखो।");
  }
}
